import { useEffect, useState } from "react";

type HeroSlide = {
  src: string;
  alt: string;
};

// الصور الثلاث من home-full-preview.html مضمّنة هنا، ولا تعتمد على مسارات public غير موجودة.
const slides: HeroSlide[] = [
  {
    src: "data:image/jpeg;base64,",
    alt: "شحن مجاني لكل اليمن",
  },
  {
    src: "data:image/jpeg;base64,",
    alt: "خصم 50% على الإلكترونيات",
  },
  {
    src: "data:image/jpeg;base64,",
    alt: "تسوّق عالمياً واستلم محلياً",
  },
];

export default function HeroFlipping() {
  const [active, setActive] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    if (paused) return;
    const timer = window.setInterval(() => {
      setActive((current) => (current + 1) % slides.length);
    }, 4000);
    return () => window.clearInterval(timer);
  }, [paused]);

  const slide = slides[active]!;

  return (
    <section className="hf-hero" dir="rtl" aria-label="العروض الحالية">
      <style>{`
        .hf-hero { padding: 16px 14px 0; }
        .hf-box {
          position: relative;
          width: 100%;
          max-width: 1000px;
          margin: 0 auto;
          overflow: hidden;
          border-radius: 24px;
          background: #0f2a5c;
          box-shadow: 0 0 0 1px rgba(56, 189, 248, .2), 0 20px 50px rgba(0, 0, 0, .5);
        }
        .hf-image-link { display: block; width: 100%; }
        .hf-image-link img { display: block; width: 100%; height: auto; object-fit: contain; }
        .hf-image-link:focus-visible { outline: 3px solid #fb923c; outline-offset: -5px; }
        .hf-dots { display: flex; align-items: center; justify-content: center; gap: 8px; padding: 8px 0 12px; }
        .hf-dots button {
          width: 10px; height: 10px; padding: 0; border: 0; border-radius: 999px;
          background: rgba(255, 255, 255, .3); cursor: pointer;
          transition: width .25s ease, background-color .25s ease;
        }
        .hf-dots button.is-active { width: 32px; background: #f97316; }
        .hf-dots button:focus-visible { outline: 2px solid #fff; outline-offset: 3px; }
        @media (max-width: 640px) { .hf-box { border-radius: 16px; } }
        @media (prefers-reduced-motion: reduce) { .hf-dots button { transition: none; } }
      `}</style>

      <div
        className="hf-box"
        onMouseEnter={() => setPaused(true)}
        onMouseLeave={() => setPaused(false)}
        onFocusCapture={() => setPaused(true)}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setPaused(false);
        }}
      >
        {/* تظهر شريحة واحدة فقط في DOM؛ لا تتراكب الصور أثناء التبديل. */}
        <a className="hf-image-link" href="/new-order" aria-label="اطلب الآن">
          <img src={slide.src} alt={slide.alt} draggable={false} />
        </a>

        <div className="hf-dots" role="group" aria-label="اختيار العرض">
          {slides.map((item, index) => (
            <button
              key={item.alt}
              type="button"
              className={active === index ? "is-active" : ""}
              aria-label={`عرض ${index + 1}: ${item.alt}`}
              aria-pressed={active === index}
              onClick={() => setActive(index)}
            />
          ))}
        </div>
      </div>
    </section>
  );
}
